// Starfield flying toward the camera.
// Brightest ("hot") stars are overbright (> 1.0) so a downstream glow/bloom can key on them.
uniform float uSpeed;     // @param 0.12 0 1.5
uniform float uDensity;   // @param 0.55 0.05 1
uniform float uHotRatio;  // @param 0.08 0 0.5
uniform float uHotGain;   // @param 4.0 1 12
uniform float uStreak;    // @param 1.5 0 6
uniform vec3  uTint;      // @param #C6D6FF
uniform vec3  uHotTint;   // @param #FFE6C4
uniform vec3  uBg;        // @param #020309

#define LAYERS 6

vec3 starLayer(vec2 p, vec2 n, float z, float seed, float depth) {
  vec2 q = p * z + seed * vec2(13.17, 7.73);
  vec2 id = floor(q);
  vec2 gv = fract(q) - 0.5;
  float stretch = 1.0 + uStreak * depth * depth * length(p);
  vec3 acc = vec3(0.0);
  for (int y = -1; y <= 1; y++) {
    for (int x = -1; x <= 1; x++) {
      vec2 o = vec2(float(x), float(y));
      vec2 cid = id + o + seed;
      if (hash(cid) > uDensity) continue;
      vec2 off = vec2(hash(cid + 3.1), hash(cid + 7.4)) - 0.5;
      vec2 d = gv - o - off * 0.8;
      // elongate along the radial (motion) direction
      float dr = dot(d, n);
      float dt = d.x * n.y - d.y * n.x;
      float r = length(vec2(dr / stretch, dt));
      float b = pow(hash(cid + 11.3), 3.0);
      float hot = step(1.0 - uHotRatio, hash(cid + 19.7));
      float size = mix(0.015, 0.05, b) + 0.03 * hot;
      float core = 1.0 - smoothstep(0.0, size, r);
      float glow = 0.0012 / (r * r + 0.0012);
      float inten = (0.25 + 0.75 * b) * (core + 0.35 * glow);
      inten *= mix(1.0, uHotGain, hot);
      vec3 c = mix(uTint, uHotTint, hot) * mix(0.85, 1.15, hash(cid + 5.5));
      acc += c * inten;
    }
  }
  return acc;
}

void main() {
  vec2 p = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);
  vec2 n = p / (length(p) + 1e-4);
  float t = iTime * uSpeed;
  vec3 col = uBg;
  for (int i = 0; i < LAYERS; i++) {
    float k = float(i) / float(LAYERS) + t;
    float depth = fract(k);
    float cycle = floor(k);
    float seed = floor(hash1(float(i) * 7.31 + cycle * 31.7) * 997.0);
    // perspective: world z shrinks linearly → screen positions accelerate outward
    float z = mix(22.0, 0.7, depth);
    float fade = smoothstep(0.0, 0.3, depth) * (1.0 - smoothstep(0.88, 1.0, depth));
    col += starLayer(p, n, z, seed, depth) * fade * (0.35 + 0.9 * depth);
  }
  // intentionally unclamped: hot stars exceed 1.0 for glow pickup
  fragColor = vec4(col, 1.0);
}
